"use strict";
/* SOLDIER MODEL: malha 3D convertida de soldierbackpack.fbx, já virada para -Z e com braços em pose de mira.
   Gerado automaticamente: 14301 vértices, 7104 triângulos, textura embutida. */
const SOLDIER_DATA={
 vc:14301,ic:21312,idxType:"u16",
 pos:"",nor:"",uv:"",
 idx:"",
 tex:"data:image/png;base64,"
};
let _soldierGeo=null,_soldierTex=null;
function _b64(s,T){const bin=atob(s),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return new T(u.buffer);}
function soldierGeometry(){
 if(_soldierGeo)return _soldierGeo;
 const g=new THREE.BufferGeometry();
 g.setAttribute('position',new THREE.BufferAttribute(_b64(SOLDIER_DATA.pos,Float32Array),3));
 g.setAttribute('normal',new THREE.BufferAttribute(_b64(SOLDIER_DATA.nor,Float32Array),3));
 g.setAttribute('uv',new THREE.BufferAttribute(_b64(SOLDIER_DATA.uv,Float32Array),2));
 g.setIndex(new THREE.BufferAttribute(_b64(SOLDIER_DATA.idx,Uint16Array),1));
 _soldierGeo=g;return g;
}
function soldierTexture(){
 if(!_soldierTex){_soldierTex=new THREE.TextureLoader().load(SOLDIER_DATA.tex);_soldierTex.wrapS=_soldierTex.wrapT=THREE.RepeatWrapping;_soldierTex.magFilter=THREE.NearestFilter;if('encoding' in _soldierTex)_soldierTex.encoding=THREE.sRGBEncoding;}
 return _soldierTex;
}
/* Cria um soldado. tint multiplica a textura clara original para dar a cor do uniforme. */
function makeSoldierMesh(tint){
 const m=new THREE.Mesh(soldierGeometry(),new THREE.MeshLambertMaterial({map:soldierTexture(),color:tint===undefined?0x292e14:tint}));
 m.castShadow=true;m.receiveShadow=false;return m;
}
